const msg = $json.message ?? $json.edited_message ?? {};
const text = String(msg.text ?? msg.caption ?? '').trim();
const chatId = String(msg.chat?.id ?? '');
const username = String(msg.from?.username ?? msg.from?.first_name ?? 'usuario');
const messageId = msg.message_id ?? null;
const valid = Boolean(chatId && text && text.length >= 2 && text.length <= 2000);
return [{json:{
  valid,
  channel:'telegram',
  message:text,
  chat_id:chatId,
  session_id:chatId,
  username,
  message_id:messageId,
  received_at:new Date().toISOString(),
  validation_error: valid ? null : 'Mensaje vacío, no textual o fuera del rango de 2 a 2000 caracteres.'
}}];

// Segundo control determinístico: aunque el Output Parser falle, el modelo responda vacío
// o el agente termine en error (onError = continuar), la decisión siempre queda en un valor permitido.
const out = $json.output;
const agentError = $json.error ? String($json.error.message ?? $json.error) : '';
let parsed = null;
if (out && typeof out === 'object') parsed = out;
else {
  const raw = String(out ?? $json.text ?? '').trim();
  try { parsed = JSON.parse(raw.replace(/^```(?:json)?/i,'').replace(/```$/,'').trim()); } catch (e) { parsed = null; }
}
if (!parsed) {
  parsed = { decision:'DERIVAR', category:'OTRO', confidence:0,
    answer:'No pude validar la respuesta automática. La consulta será revisada por una persona.',
    requires_human:true,
    reason: agentError ? 'Fallo del agente/modelo/vector store: ' + agentError : 'Respuesta vacía o no estructurada del modelo',
    sources:[] };
}
const allowed = ['RESOLVER','PEDIR_ACLARACION','DERIVAR','FUERA_DE_ALCANCE'];
let decision = String(parsed.decision ?? 'DERIVAR').toUpperCase();
let confidence = Number(parsed.confidence ?? 0);
if (!allowed.includes(decision)) decision = 'DERIVAR';
if (!Number.isFinite(confidence) || confidence < 0 || confidence > 1) confidence = 0;
if (decision === 'RESOLVER' && confidence < 0.70) decision = 'DERIVAR';
const answer = String(parsed.answer ?? '').trim().slice(0,700) || 'La consulta requiere revisión humana.';
return [{json:{
  ...$('Normalizar Telegram').item.json,
  decision, category:String(parsed.category ?? 'OTRO').toUpperCase(), confidence,
  answer, requires_human: decision === 'DERIVAR' || Boolean(parsed.requires_human),
  reason:String(parsed.reason ?? '').slice(0,500),
  sources:Array.isArray(parsed.sources) ? parsed.sources.slice(0,5) : [],
  agent_raw: typeof out === 'object' ? JSON.stringify(out) : String(out ?? ''),
  agent_error: agentError || null,
  processed_at:new Date().toISOString()
}}];

const raw = $json.content ?? $json.data ?? $json.body ?? '';
let text;
try {
  text = $json.encoding === 'base64' || /^[A-Za-z0-9+/=\n\r]+$/.test(String(raw))
    ? Buffer.from(String(raw).replace(/\s/g,''), 'base64').toString('utf8')
    : String(raw);
} catch (e) { text = String(raw); }
let docs;
try { docs = JSON.parse(text); }
catch (e) { throw new Error('data/conocimiento.json no contiene JSON válido: ' + e.message); }
if (!Array.isArray(docs)) throw new Error('La raíz de conocimiento.json debe ser un array.');
return docs.map((d,i)=>({json:{
  id:String(d.id ?? `DOC-${i+1}`),
  categoria:String(d.categoria ?? 'OTRO').toUpperCase(),
  titulo:String(d.titulo ?? 'Documento sin título').trim(),
  contenido:String(d.contenido ?? '').trim(),
  fuente:String(d.fuente ?? 'GitHub').trim(),
  activo:Boolean(d.activo),
  fecha_actualizacion:String(d.fecha_actualizacion ?? ''),
  github_sha:String($json.sha ?? ''),
  github_path:String($json.path ?? 'data/conocimiento.json')
}}));

const validCategories=['ECONOMIA','INMOBILIARIO','IMPORTACIONES','MERCADOS','OTRO'];
const text=String($json.contenido??'').trim();
const category=validCategories.includes($json.categoria)?$json.categoria:'OTRO';
const valid=Boolean($json.activo && text.length>=40 && $json.id && $json.titulo);
return {json:{
  valid,
  text,
  document_title:String($json.titulo),
  category,
  source:String($json.fuente),
  document_id:String($json.id),
  ingested_at:new Date().toISOString(),
  fecha_actualizacion:$json.fecha_actualizacion,
  github_sha:$json.github_sha,
  github_path:$json.github_path,
  validation_error:valid?null:'Documento inactivo, incompleto o contenido menor a 40 caracteres.'
}};

const e=$json.execution??$json;
return [{json:{
  workflow_name:String(e.workflow?.name??'RadarIA'),
  execution_id:String(e.id??'N/D'),
  last_node:String(e.lastNodeExecuted??'N/D'),
  error_message:String(e.error?.message??e.error??'Error no especificado'),
  error_stack:String(e.error?.stack??'').slice(0,4000),
  timestamp:new Date().toISOString()
}}];
